config.py:
"""Configuration, layered (later wins):

  1. built-in DEFAULTS
  2. ~/.promptrefiner.json            (your personal settings)
  3. ./.promptrefiner.json            (team settings, in the folder you run it from)
  4. environment variables PROMPT_REFINER_*  (model, ollama_url, port)

Lists such as team_rules are merged across files; other values are overridden.
"""

import json
import os

DEFAULTS = {
    # Local model (Ollama)
    "model": "qwen2.5:3b",
    "ollama_url": "http://localhost:11434",
    "timeout": 600,
    "num_ctx": 8192,
    "temperature": 0.1,
    # Output
    "target": "chat",                 # "chat" (paste code into the prompt) | "claude-code" (reference paths)
    "code_output": "auto",            # "auto" | "full" | "diff"
    "efficient": True,
    "save_prompts": True,
    # Team conventions, injected into every coding prompt
    "team_rules": [],                 # e.g. "Use pytest; never unittest"
    "banned": [],                     # e.g. "lodash", "Thread.sleep"
    "port": 8765,
}

_LIST_KEYS = {"team_rules", "banned"}
CONFIG_NAME = ".promptrefiner.json"


def _read(path):
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}


def load_config():
    cfg = json.loads(json.dumps(DEFAULTS))           # deep copy
    layers = [os.path.join(os.path.expanduser("~"), CONFIG_NAME), os.path.join(os.getcwd(), CONFIG_NAME)]
    for path in layers:
        for key, value in _read(path).items():
            if key in _LIST_KEYS and isinstance(value, list):
                cfg[key] = list(dict.fromkeys(cfg.get(key, []) + value))
            else:
                cfg[key] = value
    env = {"model": "PROMPT_REFINER_MODEL", "ollama_url": "PROMPT_REFINER_OLLAMA",
           "port": "PROMPT_REFINER_PORT"}
    for key, var in env.items():
        if os.environ.get(var):
            cfg[key] = int(os.environ[var]) if key == "port" else os.environ[var]
    return cfg

llm.py:
"""Ollama client with structured (JSON-schema) output, validation and one repair retry.

Any object with a `.json(system, user, schema)` method can replace OllamaLLM,
which is how the tests run without a model.
"""

import json
import re
import urllib.error
import urllib.request


class LLMError(RuntimeError):
    """Raised for anything that should fall back to rules-only output."""


def _extract_json(raw):
    try:
        return json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        pass
    m = re.search(r"\{.*\}", raw or "", re.DOTALL)
    if m:
        try:
            return json.loads(m.group(0))
        except json.JSONDecodeError:
            pass
    raise LLMError("model output was not valid JSON")


def validate(data, schema):
    """Light schema check + coercion: required keys exist, strings are strings,
    arrays are lists. Returns a cleaned dict."""
    if not isinstance(data, dict):
        raise LLMError("model output is not a JSON object")
    out = {}
    for key, spec in schema.get("properties", {}).items():
        value = data.get(key)
        if spec.get("type") == "array":
            if isinstance(value, str):
                value = [value] if value.strip() else []
            if not isinstance(value, list):
                value = []
            if spec.get("items", {}).get("type") == "object":
                value = [v for v in value if isinstance(v, (dict, str))]
            else:
                value = [_flatten(v) for v in value if _flatten(v)]
        else:
            value = _flatten(value)
        out[key] = value
    missing = [k for k in schema.get("required", []) if out.get(k) in (None, "", [])]
    if missing and len(missing) == len(schema.get("required", [])):
        raise LLMError("model output is missing: " + ", ".join(missing))
    return out


def _flatten(v):
    if v is None:
        return ""
    if isinstance(v, dict):
        v = v.get("text") or v.get("question") or v.get("value") or next(iter(v.values()), "")
    return str(v).strip()


class OllamaLLM:
    def __init__(self, cfg, model=None):
        self.url = cfg["ollama_url"].rstrip("/")
        self.model = model or cfg["model"]
        self.timeout = cfg["timeout"]
        self.options = {"temperature": cfg["temperature"], "num_ctx": cfg["num_ctx"]}

    # ---------- HTTP ----------
    def _post(self, path, payload):
        req = urllib.request.Request(self.url + path, data=json.dumps(payload).encode("utf-8"),
                                     headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "ignore")
            if e.code == 404 and "not found" in body:
                raise LLMError(f"model '{self.model}' is not installed. Run: ollama pull {self.model}") from e
            raise LLMError(f"Ollama HTTP {e.code}: {body[:200]}") from e
        except urllib.error.URLError as e:
            raise LLMError(f"cannot reach Ollama at {self.url}. Is the Ollama app running?") from e
        except TimeoutError as e:
            raise LLMError("the local model timed out. Try a smaller model.") from e

    def models(self):
        try:
            with urllib.request.urlopen(self.url + "/api/tags", timeout=5) as resp:
                data = json.loads(resp.read().decode("utf-8"))
            return sorted(m["name"] for m in data.get("models", []))
        except Exception:
            return []

    def _chat(self, messages, fmt):
        data = self._post("/api/chat", {
            "model": self.model, "messages": messages, "stream": False,
            "format": fmt, "keep_alive": "15m", "options": self.options,
        })
        return data.get("message", {}).get("content", "")

    # ---------- public ----------
    def json(self, system, user, schema):
        messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
        try:
            raw = self._chat(messages, schema)          # Ollama >= 0.5: schema-constrained output
        except LLMError as e:
            if "HTTP 400" not in str(e):
                raise
            raw = self._chat(messages, "json")          # older Ollama: plain JSON mode
        try:
            return validate(_extract_json(raw), schema)
        except LLMError as first_error:                 # one repair attempt
            messages += [{"role": "assistant", "content": raw},
                         {"role": "user", "content": f"Invalid output ({first_error}). "
                                                     "Return ONLY valid JSON with all required keys."}]
            return validate(_extract_json(self._chat(messages, "json")), schema)
